"""Parcel shipping rates, in cents."""

SMALL_PARCEL_MAX_KG = 1.0
LARGE_PARCEL_MIN_KG = 20.0


def shipping_cents(weight_kg: float) -> int:
    if weight_kg <= 0:
        raise ValueError("weight must be positive")
    if weight_kg <= SMALL_PARCEL_MAX_KG:
        return 499
    if weight_kg >= LARGE_PARCEL_MIN_KG:
        return 2999
    return 899

"""Parcel shipping rates, in cents."""

SMALL_PARCEL_MAX_KG = 1.0
LARGE_PARCEL_MIN_KG = 20.0

# (upper bound in kg, cents), checked in order.
RATE_TABLE = (
    (SMALL_PARCEL_MAX_KG, 499),
    (LARGE_PARCEL_MIN_KG, 899),
)


def shipping_cents(weight_kg: float) -> int:
    if weight_kg <= 0:
        raise ValueError("weight must be positive")
    for bound, cents in RATE_TABLE:
        if weight_kg <= bound:
            return cents
    return 2999

import pytest

from shipping.rates import shipping_cents


def test_small_parcel_up_to_and_including_1kg():
    assert shipping_cents(0.5) == 499
    assert shipping_cents(1.0) == 899


def test_standard_parcel():
    assert shipping_cents(5) == 899


class TestLargeParcels:
    @pytest.mark.parametrize("kg", [20, 35.5])
    def test_large_rate(self, kg):
        assert shipping_cents(kg) == 2999


def test_rejects_non_positive_weight():
    with pytest.raises(ValueError):
        shipping_cents(0)
